// Select fields, compute derived values, report execution time.
const start = Date.now();
const out = [];

for (const item of items) {
  const l = item.json;
  const mission = l.mission_name || 'UNKNOWN';
  const year = l.launch_year;
  const yearInt = parseInt(String(year).slice(0, 4), 10);
  const rocket = l.rocket || {};

  const row = {
    flight_number: l.flight_number,
    mission_name: mission,
    mission_slug: mission.toLowerCase().replace(/\s+/g, '-'),
    launch_year: year,
    launch_year_int: Number.isNaN(yearInt) ? null : yearInt,
    is_success: Boolean(l.launch_success),
    rocket_name: rocket.rocket_name
  };
  out.push(row);
  console.log('[etl] transformed flight ' + row.flight_number + ' -> ' + row.mission_slug);
}

const elapsed = (Date.now() - start) / 1000;
console.log('[etl] transformed ' + out.length + ' rows in ' + elapsed + 's');

return out.map(function (r) { return { json: r }; });
